#ifdef TEST_ARRAY_COPY_LIVENESS_DV
struct FUNC_MAIN_results {
  sisal_array_t res_0;
  sisal_array_t res_1;
};
extern "C" struct FUNC_MAIN_results func_MAIN(void);

static void test_array_copy_liveness_dv(void) {
  printf("\n=== Group: array_copy_liveness_dv (Array copy liveness when both A and B are live) ===\n");
  struct FUNC_MAIN_results res = func_MAIN();
  sisal_array_t A = res.res_0;
  sisal_array_t B2 = res.res_1;

  bool ok_A = (A.size == 3 && ai(A, 0) == 10 && ai(A, 1) == 20 && ai(A, 2) == 30);
  bool ok_B2 = (B2.size == 3 && ai(B2, 0) == 999 && ai(B2, 1) == 20 && ai(B2, 2) == 30);

  check("array_copy_liveness_dv A remains [10, 20, 30]", ok_A);
  check("array_copy_liveness_dv B2 modified to [999, 20, 30]", ok_B2);
  check("array_copy_liveness_dv A and B2 have separate data buffers", A.data != B2.data);
}
#endif

